"""Screens of the automation: PreparationPage, RecordFillingPage and ConclusionPage.

One class per session of the model, with what the process does on it. ``self.actions`` are the nekkora_rpa actions
(fill, click, download, read) and ``SelectorKey.<NAME>.value`` names an element of the target registry
(automation/selectors.py): the framework checks the identity and uniqueness of the element before acting. The
``step_id`` of each action links it to the Studio step (map in manifest.json).
"""

from __future__ import annotations

from pathlib import Path
from typing import ClassVar

from nekkora_rpa import Actions
from nekkora_rpa.libs.actions import DownloadedFile
from nekkora_rpa.pages import BasePage

from automation.selectors import SelectorKey

XLSX_SIGNATURE = b"PK\x03\x04"
"""First bytes of every .xlsx file: a downloaded file that does not start with them is refused."""


class PageBase(BasePage):
    """Base of the screens: readable names for the nekkora_rpa Pages API (the behavior is the framework's)."""

    identity_key: ClassVar[SelectorKey]
    """Element that proves this screen is the current one; ``BasePage.prefix`` and ``identity`` come from it."""

    def __init_subclass__(cls) -> None:
        super().__init_subclass__()
        if hasattr(cls, "identity_key"):
            cls.prefix, _, cls.identity = cls.identity_key.value.rpartition(".")

    @property
    def actions(self) -> Actions:
        """The nekkora_rpa actions on this screen (the same object as ``BasePage.act``)."""
        return self.act


class PreparationPage(PageBase):
    """Screen of the session “Preparação” (runs once, before the spreadsheet rows): downloads the spreadsheet
    (“Download Excel cloud_download”) and clicks “Start”.
    """

    identity_key = SelectorKey.PREPARATION_DOWNLOAD_EXCEL_CLOUD_DOWNLOAD

    def download_spreadsheet(self, folder: Path) -> DownloadedFile:
        """Clicks “Download Excel cloud_download” and saves the downloaded file in ``folder`` as ``challenge.xlsx``.

        The file is accepted only if it is an .xlsx (its first bytes are checked). Returns the downloaded file (path
        and SHA-256).
        """
        return self.actions.download(
            SelectorKey.PREPARATION_DOWNLOAD_EXCEL_CLOUD_DOWNLOAD.value,
            dest_dir=folder,
            file_name="challenge.xlsx",
            magic=XLSX_SIGNATURE,
            step_id="preparation.download_spreadsheet",
        )

    def click_start(self) -> None:
        """Clicks “Start”.

        Finishes when the form field “First Name” is replaced by a new one (proof that the form is ready for the
        first row).
        """
        field_before = self.actions.mark(SelectorKey.RECORD_FILLING_FIRST_NAME.value, step_id="preparation.click_start")
        self.actions.click(
            SelectorKey.PREPARATION_START.value,
            step_id="preparation.click_start",
            postcondition=lambda: self.actions.replaced(field_before),
        )


class RecordFillingPage(PageBase):
    """Screen of the session “Preenchimento por registro” (runs once per spreadsheet row): fills “First Name”, “Last
    Name”, “Company Name”, “Role in Company”, “Address”, “Email” and “Phone Number” and clicks “Submit”.
    """

    identity_key = SelectorKey.RECORD_FILLING_FIRST_NAME

    def submit_record(
        self,
        *,
        first_name: str,
        last_name: str,
        company_name: str,
        role_in_company: str,
        address: str,
        email: str,
        phone_number: str,
    ) -> None:
        """Fills “First Name”, “Last Name”, “Company Name”, “Role in Company”, “Address”, “Email” and “Phone Number”
        with the values of one spreadsheet row and clicks “Submit”.

        Finishes when the field “First Name” is replaced by a new one (proof that the form moved on). Submits only
        once: if the outcome is uncertain, the item stops (``OUTCOME_UNKNOWN``) instead of clicking “Submit” again.
        """
        self.actions.fill(
            SelectorKey.RECORD_FILLING_FIRST_NAME.value,
            first_name,
            step_id="record_filling.fill_first_name",
        )
        self.actions.fill(
            SelectorKey.RECORD_FILLING_LAST_NAME.value,
            last_name,
            step_id="record_filling.fill_last_name",
        )
        self.actions.fill(
            SelectorKey.RECORD_FILLING_COMPANY_NAME.value,
            company_name,
            step_id="record_filling.fill_company_name",
        )
        self.actions.fill(
            SelectorKey.RECORD_FILLING_ROLE_IN_COMPANY.value,
            role_in_company,
            step_id="record_filling.fill_role_in_company",
        )
        self.actions.fill(SelectorKey.RECORD_FILLING_ADDRESS.value, address, step_id="record_filling.fill_address")
        self.actions.fill(SelectorKey.RECORD_FILLING_EMAIL.value, email, step_id="record_filling.fill_email")
        self.actions.fill(
            SelectorKey.RECORD_FILLING_PHONE_NUMBER.value,
            phone_number,
            step_id="record_filling.fill_phone_number",
        )
        field_before = self.actions.mark(
            SelectorKey.RECORD_FILLING_FIRST_NAME.value,
            step_id="record_filling.click_submit",
        )
        self.actions.click(
            SelectorKey.RECORD_FILLING_SUBMIT.value,
            step_id="record_filling.click_submit",
            postcondition=lambda: self.actions.replaced(field_before),
        )


class ConclusionPage(PageBase):
    """Screen of the session “Conclusão” (runs once, after the spreadsheet rows): reads the text that matches the
    declared pattern.
    """

    prefix = "conclusion"
    """This screen uses no element of the target registry; the prefix only names it."""

    def read_result(self) -> str:
        """Reads the page text that matches the pattern declared in the generation config.

        Returns the text read.
        """
        return self.actions.read_text_matching(
            "^Your success rate is \\d+(\\.\\d+)?% \\( \\d+ out of \\d+ fields\\) in \\d+ milliseconds$",
            step_id="conclusion.read_result",
        )
